import React, { useState, useEffect } from 'react';
import { FontAwesomeIcon } from '@fortawesome/react-fontawesome';
import { faPlus, faChartBar, faList, faCog, faUser } from '@fortawesome/free-solid-svg-icons';
import { Link } from 'react-router-dom';  // Import Link from React Router

const Navbar = () => {
  const [showNavbar, setShowNavbar] = useState(true);
  const [lastScrollY, setLastScrollY] = useState(0);

  // Function to handle scroll events
  const handleScroll = () => {
    if (window.scrollY > lastScrollY) {
      // Scrolling down, hide the navbar
      setShowNavbar(false);
    } else {
      // Scrolling up, show the navbar
      setShowNavbar(true);
    }
    setLastScrollY(window.scrollY);
  };

  // Run effect on component mount and unmount
  useEffect(() => {
    window.addEventListener('scroll', handleScroll);

    // Cleanup the event listener on unmount
    return () => {
      window.removeEventListener('scroll', handleScroll);
    };
  }, [lastScrollY]);

  return (
    <div>
      {/* Top Section (Text Always Visible for large screens) */}
      <header className="header">
        <h2>ExpenseTracker</h2>
      </header>

      {/* Bottom Navbar (with Icons only for mobile) */}
      <nav className={`navbar ${showNavbar ? '' : 'hidden'}`}>
        <div className="links">
          {/* Link to Dashboard */}
          <Link to="/" className="nav-item">
            <FontAwesomeIcon icon={faChartBar} />
          </Link>
          {/* Link to Analytics */}
          <Link to="/upcoming-investments" className="nav-item">
            <FontAwesomeIcon icon={faList} />
          </Link>
          {/* Link to AddTransaction */}
          <Link to="/add-transaction" className="nav-item">
            <FontAwesomeIcon icon={faPlus} />
          </Link>
          {/* Link to Analytics (second icon, can be used differently) */}
          <Link to="/analytics" className="nav-item">
            <FontAwesomeIcon icon={faChartBar} />
          </Link>
          {/* Link to Settings or Preferences */}
          <Link to="/settings" className="nav-item">
            <FontAwesomeIcon icon={faCog} />
          </Link>
        </div>
        <div className="profile">
          {/* Link to Profile */}
          <Link to="/profile" className="nav-item">
            <FontAwesomeIcon icon={faUser} />
          </Link>
        </div>
      </nav>
    </div>
  );
};

export default Navbar;
