import React, { useState, useEffect } from "react";
import { database, ref, onValue } from "./firebase";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faCalendarAlt, faArrowRight } from "@fortawesome/free-solid-svg-icons";
import "./Upcoming-Investments.css";

const UpcomingInvestments = () => {
  const [upcomingInvestments, setUpcomingInvestments] = useState([]);
  const [currentLoans, setCurrentLoans] = useState([]);

  useEffect(() => {
    // Fetch investments from Firebase
    const investmentsRef = ref(database, "transactions");

    onValue(investmentsRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        // Filter investments based on the date or recurring type
        const futureInvestments = Object.values(data).filter((investment) => {
          const investmentDate = new Date(investment.date);
          return investmentDate > new Date() || investment.isRecurring;
        });

        setUpcomingInvestments(futureInvestments);

        // Filter loans that are pending repayment
        const loans = Object.values(data).filter((transaction) => transaction.isUdhar);
        setCurrentLoans(loans);
      }
    });
  }, []);

  // Calculate Loan Payment
  const calculateLoanPayment = (loan) => {
    const { loanAmount, loanType } = loan;
    const interestRate = loan.loanType === "borrow" ? 10 : 5; // Example interest rate logic
    const interest = (loanAmount * interestRate) / 100;
    return loanAmount + interest;
  };

  return (
    <div className="upcoming-investments-container">
      <header className="header">
        <h2>Upcoming Investments</h2>
      </header>

      <div className="investments-list">
        {upcomingInvestments.length === 0 ? (
          <p>No upcoming investments scheduled.</p>
        ) : (
          upcomingInvestments.map((investment, index) => (
            <div key={index} className="investment-card">
              <div className="investment-details">
                <h3>{investment.category}</h3>
                <p>
                  <FontAwesomeIcon icon={faCalendarAlt} /> {new Date(investment.date).toLocaleDateString()}
                </p>
                <p>Amount: ₹{investment.amount}</p>
                {investment.isUdhar && (
                  <>
                    <p>Loan Amount: ₹{investment.loanAmount}</p>
                    <p>Repayment Date: {new Date(investment.repaymentDate).toLocaleDateString()}</p>
                    <p>Total Payment: ₹{calculateLoanPayment(investment)}</p>
                  </>
                )}
              </div>
              <div className="investment-action">
                <button className="view-details-btn">
                  <FontAwesomeIcon icon={faArrowRight} />
                  View Details
                </button>
              </div>
            </div>
          ))
        )}
      </div>

      <header className="header">
        <h2>Current Loan Status</h2>
      </header>

      <div className="loans-list">
        {currentLoans.length === 0 ? (
          <p>No active loans.</p>
        ) : (
          currentLoans.map((loan, index) => (
            <div key={index} className="loan-card">
              <div className="loan-details">
                <h3>{loan.partyInvolved}</h3>
                <p>Loan Amount: ₹{loan.loanAmount}</p>
                <p>Repayment Date: {new Date(loan.repaymentDate).toLocaleDateString()}</p>
                <p>Total Payment: ₹{calculateLoanPayment(loan)}</p>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default UpcomingInvestments;
